	if len(main) < 5 {
		t.Fatalf("the main view exposes %d shortcuts, want the full set", len(main))
	}
	if !hasShortcut(main, "ctrl+n") || !hasShortcut(main, "ctrl+d") {
		t.Error("the main view does not expose the CRUD shortcuts")
	}

